WITH seed_step (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) AS (VALUES ('55555555-5555-5555-0011-000000000001'::uuid, COALESCE((SELECT id FROM recipes WHERE slug = 'nem-ran-ha-noi-gion-rum-11' LIMIT 1), (SELECT id FROM recipes WHERE id = '17ddfb98-dfed-49d6-8bd0-018ed39d1eb2'::uuid LIMIT 1)), 1, 'Bước 1: Sơ chế nguyên liệu tươi', 'Rửa sạch tất cả thịt cá và rau củ với nước muối loãng. Thịt thấm khô bằng khăn giấy chuyên dụng trước khi tẩm ướp. Rau thơm nhặt lá non, để thật ráo nước.', 10, NOW(), false)) INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) SELECT seed_step.* FROM seed_step WHERE NOT EXISTS (SELECT 1 FROM recipe_steps rs WHERE rs.id = seed_step.id OR (rs.recipe_id = seed_step.recipe_id AND rs.step_number = seed_step.step_number));
WITH seed_step (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) AS (VALUES ('55555555-5555-5555-0011-000000000002'::uuid, COALESCE((SELECT id FROM recipes WHERE slug = 'nem-ran-ha-noi-gion-rum-11' LIMIT 1), (SELECT id FROM recipes WHERE id = '17ddfb98-dfed-49d6-8bd0-018ed39d1eb2'::uuid LIMIT 1)), 2, 'Bước 2: Pha chế sốt ướp bí truyền', 'Cho tỏi băm, hành phi, nước mắm ngon, tiêu đen, mật ong và dầu hào vào âu lớn. Khuấy đều tay đến khi các gia vị tan hoàn toàn và hòa quyện thành hỗn hợp sánh mịn.', 8, NOW(), false)) INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) SELECT seed_step.* FROM seed_step WHERE NOT EXISTS (SELECT 1 FROM recipe_steps rs WHERE rs.id = seed_step.id OR (rs.recipe_id = seed_step.recipe_id AND rs.step_number = seed_step.step_number));
WITH seed_step (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) AS (VALUES ('55555555-5555-5555-0011-000000000003'::uuid, COALESCE((SELECT id FROM recipes WHERE slug = 'nem-ran-ha-noi-gion-rum-11' LIMIT 1), (SELECT id FROM recipes WHERE id = '17ddfb98-dfed-49d6-8bd0-018ed39d1eb2'::uuid LIMIT 1)), 3, 'Bước 3: Tẩm ướp thấm đượm gia vị', 'Trút phần thịt vào âu gia vị sốt ướp, dùng tay mát xa nhẹ nhàng từng thớ thịt. Đậy kín màng bọc thực phẩm và giữ trong ngăn mát tủ lạnh ít nhất 30-45 phút.', 35, NOW(), false)) INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) SELECT seed_step.* FROM seed_step WHERE NOT EXISTS (SELECT 1 FROM recipe_steps rs WHERE rs.id = seed_step.id OR (rs.recipe_id = seed_step.recipe_id AND rs.step_number = seed_step.step_number));
WITH seed_step (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) AS (VALUES ('55555555-5555-5555-0011-000000000004'::uuid, COALESCE((SELECT id FROM recipes WHERE slug = 'nem-ran-ha-noi-gion-rum-11' LIMIT 1), (SELECT id FROM recipes WHERE id = '17ddfb98-dfed-49d6-8bd0-018ed39d1eb2'::uuid LIMIT 1)), 4, 'Bước 4: Hầm nước dùng / Ninh lửa nhỏ', 'Bắc nồi lên bếp, cho xương đã chần và túi thảo mộc thơm vào cùng 2 lít nước sôi. Hạ lửa nhỏ liu riu, thường xuyên hớt bọt để nước trong suốt óng ả.', 60, NOW(), false)) INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) SELECT seed_step.* FROM seed_step WHERE NOT EXISTS (SELECT 1 FROM recipe_steps rs WHERE rs.id = seed_step.id OR (rs.recipe_id = seed_step.recipe_id AND rs.step_number = seed_step.step_number));
