WITH seed_step (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) AS (VALUES ('55555555-5555-5555-0027-000000000003'::uuid, COALESCE((SELECT id FROM recipes WHERE slug = 'suon-cuu-nuong-huong-thao-toi-dap-27' LIMIT 1), (SELECT id FROM recipes WHERE id = '8c34906a-331e-4aa3-bfc7-6eb7ce6657aa'::uuid LIMIT 1)), 3, 'Bước 3: Tẩm ướp thấm đượm gia vị', 'Trút phần thịt vào âu gia vị sốt ướp, dùng tay mát xa nhẹ nhàng từng thớ thịt. Đậy kín màng bọc thực phẩm và giữ trong ngăn mát tủ lạnh ít nhất 30-45 phút.', 35, NOW(), false)) INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) SELECT seed_step.* FROM seed_step WHERE NOT EXISTS (SELECT 1 FROM recipe_steps rs WHERE rs.id = seed_step.id OR (rs.recipe_id = seed_step.recipe_id AND rs.step_number = seed_step.step_number));
WITH seed_step (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) AS (VALUES ('55555555-5555-5555-0027-000000000004'::uuid, COALESCE((SELECT id FROM recipes WHERE slug = 'suon-cuu-nuong-huong-thao-toi-dap-27' LIMIT 1), (SELECT id FROM recipes WHERE id = '8c34906a-331e-4aa3-bfc7-6eb7ce6657aa'::uuid LIMIT 1)), 4, 'Bước 4: Hầm nước dùng / Ninh lửa nhỏ', 'Bắc nồi lên bếp, cho xương đã chần và túi thảo mộc thơm vào cùng 2 lít nước sôi. Hạ lửa nhỏ liu riu, thường xuyên hớt bọt để nước trong suốt óng ả.', 60, NOW(), false)) INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) SELECT seed_step.* FROM seed_step WHERE NOT EXISTS (SELECT 1 FROM recipe_steps rs WHERE rs.id = seed_step.id OR (rs.recipe_id = seed_step.recipe_id AND rs.step_number = seed_step.step_number));
WITH seed_step (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) AS (VALUES ('55555555-5555-5555-0027-000000000005'::uuid, COALESCE((SELECT id FROM recipes WHERE slug = 'suon-cuu-nuong-huong-thao-toi-dap-27' LIMIT 1), (SELECT id FROM recipes WHERE id = '8c34906a-331e-4aa3-bfc7-6eb7ce6657aa'::uuid LIMIT 1)), 5, 'Bước 5: Chế biến nhiệt / Xào nấu chín tới', 'Làm nóng chảo sâu lòng với chút mỡ hành hoặc dầu ăn. Trút nguyên liệu vào đảo nhanh tay trên lửa lớn đến khi săn lại, dậy mùi thơm nức mũi và giữ trọn độ mọng nước.', 15, NOW(), false)) INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) SELECT seed_step.* FROM seed_step WHERE NOT EXISTS (SELECT 1 FROM recipe_steps rs WHERE rs.id = seed_step.id OR (rs.recipe_id = seed_step.recipe_id AND rs.step_number = seed_step.step_number));
