WITH seed_step (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) AS (VALUES ('55555555-5555-5555-0068-000000000004'::uuid, COALESCE((SELECT id FROM recipes WHERE slug = 'pha-lau-bo-nuoc-cot-dua-cham-banh-mi-68' LIMIT 1), (SELECT id FROM recipes WHERE id = 'ca3aee88-f89a-4707-a2d3-95ddba993fd0'::uuid LIMIT 1)), 4, 'Bước 4: Hầm nước dùng / Ninh lửa nhỏ', 'Bắc nồi lên bếp, cho xương đã chần và túi thảo mộc thơm vào cùng 2 lít nước sôi. Hạ lửa nhỏ liu riu, thường xuyên hớt bọt để nước trong suốt óng ả.', 60, NOW(), false)) INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) SELECT seed_step.* FROM seed_step WHERE NOT EXISTS (SELECT 1 FROM recipe_steps rs WHERE rs.id = seed_step.id OR (rs.recipe_id = seed_step.recipe_id AND rs.step_number = seed_step.step_number));
WITH seed_step (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) AS (VALUES ('55555555-5555-5555-0068-000000000005'::uuid, COALESCE((SELECT id FROM recipes WHERE slug = 'pha-lau-bo-nuoc-cot-dua-cham-banh-mi-68' LIMIT 1), (SELECT id FROM recipes WHERE id = 'ca3aee88-f89a-4707-a2d3-95ddba993fd0'::uuid LIMIT 1)), 5, 'Bước 5: Chế biến nhiệt / Xào nấu chín tới', 'Làm nóng chảo sâu lòng với chút mỡ hành hoặc dầu ăn. Trút nguyên liệu vào đảo nhanh tay trên lửa lớn đến khi săn lại, dậy mùi thơm nức mũi và giữ trọn độ mọng nước.', 15, NOW(), false)) INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) SELECT seed_step.* FROM seed_step WHERE NOT EXISTS (SELECT 1 FROM recipe_steps rs WHERE rs.id = seed_step.id OR (rs.recipe_id = seed_step.recipe_id AND rs.step_number = seed_step.step_number));
WITH seed_step (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) AS (VALUES ('55555555-5555-5555-0068-000000000006'::uuid, COALESCE((SELECT id FROM recipes WHERE slug = 'pha-lau-bo-nuoc-cot-dua-cham-banh-mi-68' LIMIT 1), (SELECT id FROM recipes WHERE id = 'ca3aee88-f89a-4707-a2d3-95ddba993fd0'::uuid LIMIT 1)), 6, 'Bước 6: Nêm nếm hoàn thiện hương vị', 'Nếm thử nước sốt, điều chỉnh lượng nước mắm và đường phèn sao cho đạt độ cân bằng tuyệt đối giữa mặn, ngọt, chua thanh và the cay nhẹ nơi đầu lưỡi.', 5, NOW(), false)) INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) SELECT seed_step.* FROM seed_step WHERE NOT EXISTS (SELECT 1 FROM recipe_steps rs WHERE rs.id = seed_step.id OR (rs.recipe_id = seed_step.recipe_id AND rs.step_number = seed_step.step_number));
