WITH seed_step (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) AS (VALUES ('55555555-5555-5555-0089-000000000005'::uuid, COALESCE((SELECT id FROM recipes WHERE slug = 'nem-lui-nuong-sa-cham-nuoc-leo-dau-phong-89' LIMIT 1), (SELECT id FROM recipes WHERE id = '8fc602d9-166d-4dca-b9d3-7a17c54651c6'::uuid LIMIT 1)), 5, 'Bước 5: Chế biến nhiệt / Xào nấu chín tới', 'Làm nóng chảo sâu lòng với chút mỡ hành hoặc dầu ăn. Trút nguyên liệu vào đảo nhanh tay trên lửa lớn đến khi săn lại, dậy mùi thơm nức mũi và giữ trọn độ mọng nước.', 15, NOW(), false)) INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) SELECT seed_step.* FROM seed_step WHERE NOT EXISTS (SELECT 1 FROM recipe_steps rs WHERE rs.id = seed_step.id OR (rs.recipe_id = seed_step.recipe_id AND rs.step_number = seed_step.step_number));
