WITH seed_step (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) AS (VALUES ('55555555-5555-5555-0093-000000000006'::uuid, COALESCE((SELECT id FROM recipes WHERE slug = 'mam-nem-pha-dua-chua-ngot-cham-bo-cuon-93' LIMIT 1), (SELECT id FROM recipes WHERE id = '91b3e480-b522-4f61-aae5-1acef9e644ba'::uuid LIMIT 1)), 6, 'Bước 6: Nêm nếm hoàn thiện hương vị', 'Nếm thử nước sốt, điều chỉnh lượng nước mắm và đường phèn sao cho đạt độ cân bằng tuyệt đối giữa mặn, ngọt, chua thanh và the cay nhẹ nơi đầu lưỡi.', 5, NOW(), false)) INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) SELECT seed_step.* FROM seed_step WHERE NOT EXISTS (SELECT 1 FROM recipe_steps rs WHERE rs.id = seed_step.id OR (rs.recipe_id = seed_step.recipe_id AND rs.step_number = seed_step.step_number));
