-- 7. Safety net for pre-existing recipes not represented by this seed file.
-- Only adds placeholder rows when a recipe has fewer than 10 ingredients or 5 steps.
-- Existing rows are never updated or deleted. These are clearly labeled supplemental records.
WITH ingredient_gaps AS (
    SELECT r.id AS recipe_id,
           r.title,
           COUNT(ri.id)::int AS current_count,
           COALESCE(MAX(ri.sort_order), 0)::int AS max_order
    FROM recipes r
    LEFT JOIN recipe_ingredients ri ON ri.recipe_id = r.id
    GROUP BY r.id, r.title
    HAVING COUNT(ri.id) < 10
)
SELECT
    md5(g.recipe_id::text || ':culinaryblog-seed-extra-ingredient:' || n)::uuid,
    g.recipe_id,
    'Nguyên liệu bổ sung ' || lpad(n::text, 2, '0') || ' - ' || left(g.title, 100),
    1.0,
    'phần',
    'Dữ liệu bổ sung tự động để đạt tối thiểu 10 nguyên liệu; cần thay bằng nguyên liệu thực tế.',
    g.max_order + n,
    NOW(),
    false
FROM ingredient_gaps g
CROSS JOIN LATERAL generate_series(1, 10 - g.current_count) AS gs(n)
ON CONFLICT DO NOTHING;

WITH step_gaps AS (
    SELECT r.id AS recipe_id,
           r.title,
           COUNT(rs.id)::int AS current_count,
           COALESCE(MAX(rs.step_number), 0)::int AS max_step
    FROM recipes r
    LEFT JOIN recipe_steps rs ON rs.recipe_id = r.id
    GROUP BY r.id, r.title
    HAVING COUNT(rs.id) < 5
)
SELECT
    md5(g.recipe_id::text || ':culinaryblog-seed-extra-step:' || n)::uuid,
    g.recipe_id,
    g.max_step + n,
    'Bước bổ sung ' || lpad(n::text, 2, '0'),
    'Bước tạm để hoàn thiện dữ liệu mẫu cho công thức "' || left(g.title, 150) || '". Hãy thay bằng hướng dẫn chế biến thực tế trước khi xuất bản.',
    0,
    NOW(),
    false
FROM step_gaps g
CROSS JOIN LATERAL generate_series(1, 5 - g.current_count) AS gs(n)
WHERE NOT EXISTS (
    SELECT 1 FROM recipe_steps rs
    WHERE rs.recipe_id = g.recipe_id AND rs.step_number = g.max_step + n
)
AND NOT EXISTS (
    SELECT 1 FROM recipe_steps rs
    WHERE rs.id = md5(g.recipe_id::text || ':culinaryblog-seed-extra-step:' || n)::uuid
);

COMMIT;
